import { prisma } from "@/lib/db";
import type { InvoiceStatus } from "@prisma/client";

export function computeTax(params: {
  taxableValuePaise: number;
  supplierState: string;
  placeOfSupply: string;
  gstRateBps?: number;
}): { cgst: number; sgst: number; igst: number; total: number } {
  const gstRateBps = params.gstRateBps ?? 1800; // 18% default
  const taxAmount = Math.round((params.taxableValuePaise * gstRateBps) / 10000);

  let cgst = 0;
  let sgst = 0;
  let igst = 0;

  if (params.supplierState === params.placeOfSupply) {
    cgst = Math.round(taxAmount / 2);
    sgst = taxAmount - cgst;
  } else {
    igst = taxAmount;
  }

  const total = params.taxableValuePaise + cgst + sgst + igst;

  return { cgst, sgst, igst, total };
}

export async function generateInvoiceNumber(): Promise<string> {
  const now = new Date();
  const year = now.getFullYear();
  const month = String(now.getMonth() + 1).padStart(2, "0");
  const monthPrefix = `${year}${month}`;

  const startOfMonth = new Date(year, now.getMonth(), 1);
  const endOfMonth = new Date(year, now.getMonth() + 1, 0, 23, 59, 59, 999);

  const count = await prisma.enterpriseInvoice.count({
    where: {
      createdAt: {
        gte: startOfMonth,
        lte: endOfMonth,
      },
    },
  });

  const sequentialCount = String(count + 1).padStart(4, "0");
  return `PS-INV-${monthPrefix}-${sequentialCount}`;
}

export async function createInvoice(data: {
  organizationId: string;
  contractId?: string;
  supplierGstin?: string;
  customerGstin?: string;
  placeOfSupply?: string;
  billingAddress?: string;
  serviceAddress?: string;
  sacCode?: string;
  taxableValuePaise: number;
  supplierState?: string;
  gstRateBps?: number;
  dueDate: Date;
  poReference?: string;
  notes?: string;
}) {
  const invoiceNumber = await generateInvoiceNumber();

  let cgst = 0;
  let sgst = 0;
  let igst = 0;
  let totalAmount = data.taxableValuePaise;

  if (data.supplierState && data.placeOfSupply) {
    const tax = computeTax({
      taxableValuePaise: data.taxableValuePaise,
      supplierState: data.supplierState,
      placeOfSupply: data.placeOfSupply,
      gstRateBps: data.gstRateBps,
    });
    cgst = tax.cgst;
    sgst = tax.sgst;
    igst = tax.igst;
    totalAmount = tax.total;
  }

  return prisma.enterpriseInvoice.create({
    data: {
      invoiceNumber,
      organizationId: data.organizationId,
      contractId: data.contractId,
      supplierGstin: data.supplierGstin,
      customerGstin: data.customerGstin,
      placeOfSupply: data.placeOfSupply,
      billingAddress: data.billingAddress,
      serviceAddress: data.serviceAddress,
      sacCode: data.sacCode,
      taxableValue: data.taxableValuePaise,
      cgst,
      sgst,
      igst,
      totalAmount,
      status: "DRAFT_INVOICE" as InvoiceStatus,
      dueDate: data.dueDate,
      poReference: data.poReference,
      notes: data.notes,
    },
  });
}

export async function sendInvoice(id: string) {
  const invoice = await prisma.enterpriseInvoice.findUnique({ where: { id } });
  if (!invoice) throw new Error("Invoice not found");
  if (invoice.status !== "DRAFT_INVOICE") {
    throw new Error("Only draft invoices can be sent");
  }

  return prisma.enterpriseInvoice.update({
    where: { id },
    data: { status: "SENT" as InvoiceStatus },
  });
}

export async function recordPayment(id: string, amountPaise: number) {
  return prisma.$transaction(async (tx) => {
    const invoice = await tx.enterpriseInvoice.findUnique({ where: { id } });
    if (!invoice) throw new Error("Invoice not found");
    if (invoice.status === "PAID" || invoice.status === "CANCELLED_INVOICE") {
      throw new Error("Cannot record payment for PAID or CANCELLED_INVOICE");
    }

    const newAmountPaid = invoice.amountPaid + amountPaise;
    let newStatus = invoice.status;
    let paidAt = invoice.paidAt;

    if (newAmountPaid >= invoice.totalAmount) {
      newStatus = "PAID" as InvoiceStatus;
      paidAt = new Date();
    } else {
      newStatus = "PARTIALLY_PAID" as InvoiceStatus;
    }

    return tx.enterpriseInvoice.update({
      where: { id },
      data: {
        amountPaid: newAmountPaid,
        status: newStatus,
        paidAt,
      },
    });
  });
}

export async function issueCreditNote(invoiceId: string, reason?: string) {
  return prisma.$transaction(async (tx) => {
    const original = await tx.enterpriseInvoice.findUnique({ where: { id: invoiceId } });
    if (!original) throw new Error("Invoice not found");

    const creditNoteNumber = await generateInvoiceNumber();

    const creditNote = await tx.enterpriseInvoice.create({
      data: {
        invoiceNumber: creditNoteNumber,
        organizationId: original.organizationId,
        contractId: original.contractId,
        supplierGstin: original.supplierGstin,
        customerGstin: original.customerGstin,
        placeOfSupply: original.placeOfSupply,
        billingAddress: original.billingAddress,
        serviceAddress: original.serviceAddress,
        sacCode: original.sacCode,
        taxableValue: -original.taxableValue,
        cgst: -original.cgst,
        sgst: -original.sgst,
        igst: -original.igst,
        totalAmount: -original.totalAmount,
        amountPaid: 0,
        currency: original.currency,
        status: "DRAFT_INVOICE" as InvoiceStatus,
        dueDate: new Date(),
        poReference: original.poReference,
        notes: reason,
        creditNoteOf: invoiceId,
      },
    });

    await tx.enterpriseInvoice.update({
      where: { id: invoiceId },
      data: { status: "CREDIT_NOTED" as InvoiceStatus },
    });

    return creditNote;
  });
}

export async function listInvoices(filters: {
  organizationId?: string;
  status?: InvoiceStatus;
  overdue?: boolean;
  page?: number;
  pageSize?: number;
}) {
  const page = filters.page ?? 1;
  const pageSize = filters.pageSize ?? 20;

  const where: any = {};

  if (filters.organizationId) {
    where.organizationId = filters.organizationId;
  }
  if (filters.status) {
    where.status = filters.status;
  }

  if (filters.overdue) {
    where.dueDate = { lt: new Date() };
    where.status = { in: ["SENT", "PARTIALLY_PAID"] as InvoiceStatus[] };
  }

  const [items, total] = await prisma.$transaction([
    prisma.enterpriseInvoice.findMany({
      where,
      include: { organization: { select: { displayName: true } } },
      skip: (page - 1) * pageSize,
      take: pageSize,
      orderBy: { createdAt: "desc" },
    }),
    prisma.enterpriseInvoice.count({ where }),
  ]);

  return { items, total, page, pageSize };
}

export async function getInvoice(id: string) {
  return prisma.enterpriseInvoice.findUnique({
    where: { id },
    include: { organization: true },
  });
}

import { prisma } from "@/lib/db";
import type { 
  ProgrammeType, 
  EligibilityMethod, 
  ProgrammeStatus, 
  MemberVerificationStatus 
} from "@prisma/client";

export async function createProgramme(data: {
  organizationId: string;
  contractId?: string;
  name: string;
  slug: string;
  programmeType: ProgrammeType;
  cityScope?: string[];
  eligibilityMethod?: EligibilityMethod;
  eligibilityDomain?: string;
  startDate?: Date;
  endDate?: Date;
  accountManagerId?: string;
  metadata?: unknown;
}) {
  return await prisma.partnerProgramme.create({
    data: {
      ...data,
      metadata: data.metadata ? (data.metadata as any) : undefined,
      status: "DRAFT_PROGRAMME",
    },
  });
}

export async function activateProgramme(id: string) {
  const programme = await prisma.partnerProgramme.findUnique({
    where: { id },
    select: { status: true },
  });

  if (!programme) {
    throw new Error("Programme not found");
  }

  if (programme.status !== "DRAFT_PROGRAMME" && programme.status !== "PAUSED_PROGRAMME") {
    throw new Error("Programme can only be activated from DRAFT or PAUSED status");
  }

  return await prisma.partnerProgramme.update({
    where: { id },
    data: { status: "ACTIVE_PROGRAMME" },
  });
}

export async function pauseProgramme(id: string) {
  const programme = await prisma.partnerProgramme.findUnique({
    where: { id },
    select: { status: true },
  });

  if (!programme) {
    throw new Error("Programme not found");
  }

  if (programme.status !== "ACTIVE_PROGRAMME") {
    throw new Error("Programme can only be paused from ACTIVE status");
  }

  return await prisma.partnerProgramme.update({
    where: { id },
    data: { status: "PAUSED_PROGRAMME" },
  });
}

export async function getProgrammeBySlug(slug: string) {
  const programme = await prisma.partnerProgramme.findUnique({
    where: { slug },
    include: {
      organization: {
        select: {
          displayName: true,
          organizationType: true,
        },
      },
      _count: {
        select: {
          memberships: true,
        },
      },
    },
  });

  if (!programme) {
    throw new Error("Programme not found");
  }

  return programme;
}

export async function enrollMember(programmeId: string, customerId: string, verificationMethod?: EligibilityMethod) {
  const programme = await prisma.partnerProgramme.findUnique({
    where: { id: programmeId },
    select: { eligibilityMethod: true },
  });

  if (!programme) {
    throw new Error("Programme not found");
  }

  const isAccessOpen = programme.eligibilityMethod === "OPEN_ACCESS";

  return await prisma.programmeMembership.create({
    data: {
      programmeId,
      customerId,
      verificationMethod: verificationMethod || programme.eligibilityMethod,
      verificationStatus: isAccessOpen ? "VERIFIED" : "PENDING_VERIFICATION",
      verifiedAt: isAccessOpen ? new Date() : null,
      active: true,
    },
  });
}

export async function verifyMember(membershipId: string, verified: boolean) {
  const status: MemberVerificationStatus = verified ? "VERIFIED" : "REJECTED_VERIFICATION";
  const verifiedAt = verified ? new Date() : null;

  return await prisma.programmeMembership.update({
    where: { id: membershipId },
    data: {
      verificationStatus: status,
      verifiedAt,
    },
  });
}

export async function listProgrammeMembers(
  programmeId: string,
  filters?: { status?: MemberVerificationStatus; page?: number; pageSize?: number }
) {
  const page = filters?.page || 1;
  const pageSize = filters?.pageSize || 10;
  const skip = (page - 1) * pageSize;

  const where: any = { programmeId };
  if (filters?.status) {
    where.verificationStatus = filters.status;
  }

  const [items, total] = await Promise.all([
    prisma.programmeMembership.findMany({
      where,
      skip,
      take: pageSize,
      include: {
        customer: {
          select: {
            id: true,
            email: true,
          },
        },
      },
      orderBy: { createdAt: "desc" },
    }),
    prisma.programmeMembership.count({ where }),
  ]);

  return { items, total, page, pageSize };
}

export async function listProgrammes(
  filters: { organizationId?: string; status?: ProgrammeStatus; type?: ProgrammeType; page?: number; pageSize?: number }
) {
  const page = filters.page || 1;
  const pageSize = filters.pageSize || 10;
  const skip = (page - 1) * pageSize;

  const where: any = {};
  if (filters.organizationId) {
    where.organizationId = filters.organizationId;
  }
  if (filters.status) {
    where.status = filters.status;
  }
  if (filters.type) {
    where.programmeType = filters.type;
  }

  const [items, total] = await Promise.all([
    prisma.partnerProgramme.findMany({
      where,
      skip,
      take: pageSize,
      include: {
        organization: {
          select: {
            displayName: true,
          },
        },
        _count: {
          select: {
            memberships: true,
          },
        },
      },
      orderBy: { createdAt: "desc" },
    }),
    prisma.partnerProgramme.count({ where }),
  ]);

  return { items, total, page, pageSize };
}

import { prisma } from "@/lib/db";
import type { Prisma } from "@prisma/client";

export async function createPromotionCode(data: {
  programmeId?: string;
  code: string;
  discountType: 'PERCENTAGE' | 'FIXED';
  discountValue: number;
  maximumDiscount?: number;
  minimumOrder?: number;
  totalUsageLimit?: number;
  perMemberLimit?: number;
  serviceScope?: string[];
  cityScope?: string[];
  validFrom: Date;
  validUntil: Date;
}) {
  return prisma.promotionCode.create({
    data: {
      ...data,
      active: true,
      perMemberLimit: data.perMemberLimit ?? 1,
    }
  });
}

export async function validateCode(
  code: string,
  context: {
    orderAmountPaise: number;
    serviceCode?: string;
    cityId?: string;
    customerId: string;
  }
): Promise<{ valid: boolean; discountPaise: number; reason?: string }> {
  const promotion = await prisma.promotionCode.findUnique({
    where: { code }
  });

  if (!promotion) {
    return { valid: false, discountPaise: 0, reason: "Invalid code" };
  }

  if (!promotion.active) {
    return { valid: false, discountPaise: 0, reason: "Code is not active" };
  }

  const now = new Date();
  if (now < promotion.validFrom || now > promotion.validUntil) {
    return { valid: false, discountPaise: 0, reason: "Code is expired or not yet valid" };
  }

  if (promotion.minimumOrder && context.orderAmountPaise < promotion.minimumOrder) {
    return { valid: false, discountPaise: 0, reason: "Minimum order amount not met" };
  }

  if (promotion.serviceScope && promotion.serviceScope.length > 0 && context.serviceCode) {
    if (!promotion.serviceScope.includes(context.serviceCode)) {
      return { valid: false, discountPaise: 0, reason: "Code not applicable for this service" };
    }
  }

  if (promotion.cityScope && promotion.cityScope.length > 0 && context.cityId) {
    if (!promotion.cityScope.includes(context.cityId)) {
      return { valid: false, discountPaise: 0, reason: "Code not applicable in this city" };
    }
  }

  if (promotion.totalUsageLimit !== null) {
    const totalUsage = await (prisma as any).benefitLedgerEntry.count({
      where: { reference: code }
    });
    if (totalUsage >= promotion.totalUsageLimit) {
      return { valid: false, discountPaise: 0, reason: "Total usage limit reached" };
    }
  }

  if (promotion.perMemberLimit !== null) {
    const memberUsage = await (prisma as any).benefitLedgerEntry.count({
      where: { reference: code, customerId: context.customerId }
    });
    if (memberUsage >= promotion.perMemberLimit) {
      return { valid: false, discountPaise: 0, reason: "Per member usage limit reached" };
    }
  }

  let discountPaise = 0;
  if (promotion.discountType === 'PERCENTAGE') {
    discountPaise = Math.floor((context.orderAmountPaise * promotion.discountValue) / 10000);
    if (promotion.maximumDiscount !== null && discountPaise > promotion.maximumDiscount) {
      discountPaise = promotion.maximumDiscount;
    }
  } else if (promotion.discountType === 'FIXED') {
    discountPaise = promotion.discountValue;
  }

  if (discountPaise > context.orderAmountPaise) {
    discountPaise = context.orderAmountPaise;
  }

  return { valid: true, discountPaise };
}

export async function deactivateCode(id: string) {
  return prisma.promotionCode.update({
    where: { id },
    data: { active: false }
  });
}

export async function listCodes(filters: {
  programmeId?: string;
  active?: boolean;
  page?: number;
  pageSize?: number;
}): Promise<{ items: any[]; total: number }> {
  const { page = 1, pageSize = 20, programmeId, active } = filters;
  const skip = (page - 1) * pageSize;
  const take = pageSize;

  const where: any = {};
  if (programmeId !== undefined) where.programmeId = programmeId;
  if (active !== undefined) where.active = active;

  const [items, total] = await Promise.all([
    prisma.promotionCode.findMany({
      where,
      skip,
      take,
      orderBy: { createdAt: 'desc' }
    }),
    prisma.promotionCode.count({ where })
  ]);

  return { items, total };
}
